local util = require 'XLua.util'
local CoWait = CS.Engine.Lib.CoWait
local kTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
------------ import ------------
local MaidCoffeeUtils = import("Game.MaidCoffee.MaidCoffeeUtils")
local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
------------ import ------------

------------ define ------------
local OrderCellNodePath = 'Game.MaidCoffee.TakeoutOrderCellNode'
local HeadNodePath = 'Game.MaidCoffee.TakeoutTeamHeadNode'
local Status = {
    IDLE = 0, --空闲中
    PROGRESSING = 1, ---配送中
    FINISHED = 2, ---已完成
}

local PER_TEAM_CARDS = 5 ---每个队最多5张卡

------------ define ------------

---@class CoffeeTakeoutPopupDialog
---@field controller                        Engine.Modules.LuaBehaviour | Engine.UI.UILuaDialog
---@field FontStyleButton2                UnityEngine.RectTransform
---@field FontStyleButton                UnityEngine.RectTransform
---@field BtnGroup                        UnityEngine.RectTransform
---@field TextTips                        UnityEngine.UI.Text
---@field UnderwayTips                    UnityEngine.RectTransform
---@field TeamMember                        UnityEngine.RectTransform
---@field BtnArrowL                        UnityEngine.RectTransform
---@field BtnArrowR                        UnityEngine.RectTransform
---@field OverseaManageTakeoutCardNode    UnityEngine.RectTransform
---@field Cell                            UnityEngine.RectTransform @属性加成的格子
---@field Content                        UnityEngine.RectTransform @内容窗器节点
---@field ScrollView                        UnityEngine.RectTransform
---@field Empty                        UnityEngine.RectTransform
local CoffeeTakeoutPopupDialog = Class("CoffeeTakeoutPopupDialog")

function CoffeeTakeoutPopupDialog:__init()
    self.data = nil
    self.deliveryButtonEnv = nil
    self.canOrder = 1
    self.selectIndex = 1
    self.teams = nil
    self.emptyClose = nil
end

function CoffeeTakeoutPopupDialog:__delete()
    self.data = nil
    self.controller = nil
    self.deliveryButtonEnv = nil
    self.selectIndex = 0
    self.teams = nil
    self.canOrder = 0
    self.emptyClose = nil
    if self.onCellCallBackEvent then
        Events.RemoveListener(MaidCoffeeConstants.EventNames.MaidCoffeeDeliveryManChange, self.onCellCallBackEvent)
        self.onCellCallBackEvent = nil
    end
end

function CoffeeTakeoutPopupDialog:InitData()
    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    maidCoffeePlayerComponent:FixTeams()
end

function CoffeeTakeoutPopupDialog:Awake()
    self.onCellCallBackEvent = Events.AddListener(MaidCoffeeConstants.EventNames.MaidCoffeeDeliveryManChange,Bind(self,self.SelectRoleCallback))
    self:InitData()
    self.emptyClose = self.controller.transform:Find("EmptyClose")
    self.Empty = self.ScrollView.transform.parent:Find("Empty")
    if self.emptyClose then
        SetButtonAction(self.emptyClose.gameObject, function()
            UIModule.BackDialog()
        end)
    end

    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local allTeam = maidCoffeePlayerComponent:GetAllTeam()
    local teamIds = {}
    for teamId, v in pairs(allTeam) do
        local status = maidCoffeePlayerComponent:GetTakeoutTeamStatus(teamId)
        if status ~= MaidCoffeeConstants.TakeOutStatus.LOCKED then
            ---已解锁的队伍
            table.insert(teamIds, checkNumber(teamId))
        end
    end
    table.sort(teamIds)
    self.teams = teamIds
    self.data = checkTable(self.controller.Argument.parameters)

    if checkNumber(self.data.teamId) == 0 then
        ---未给选中的队伍，从列中选中一个
        if #self.teams > 0 then
            local selectIndex = 1
            for index, teamId in pairs(self.teams) do
                local status = maidCoffeePlayerComponent:GetTakeoutTeamStatus(teamId)
                if status == MaidCoffeeConstants.TakeOutStatus.IDLE then
                    selectIndex = index
                    break
                end
            end
            self.selectIndex = selectIndex
        end
    else
        if #self.teams > 0 then
            self.selectIndex = 1 ---如果保存的编队大于1，选中第一队队伍
            local selectedTeamId = checkNumber(self.data.teamId)
            for index, teamId in pairs(self.teams) do
                if checkNumber(teamId) == selectedTeamId then
                    self.selectIndex = index
                    break
                end
            end
        end
    end
    self.deliveryButtonEnv = self.FontStyleButton2:GetComponent("FontStyleButton")

    local count = self.TeamMember.transform.childCount
    for i = 1, count do
        local button = self.TeamMember.transform:GetChild(i - 1)
        SetButtonAction(button, function()
            self:OnTeamCardAction(i)
        end)
    end
    ---@type Game.Native.Common.FontStyleButton
    local deliveryButtonEnv = self.FontStyleButton:GetComponent("FontStyleButton")
    if deliveryButtonEnv then
        deliveryButtonEnv:ResetFontStyle("B6", localize('快速上阵'))
    end
    SetButtonAction(self.FontStyleButton, function()
        ---快速编队
        ---@type CardComponent
        local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
        local t = cardComponent:GetAllCardTable()
        local showCard = {}
        --local limitStatus2Status = MaidCoffeeUtils.GetMaidCoffeeCardStatusLimit(MaidCoffeeConstants.CafeStatus.InTakeaway)
        ---过滤掉外卖中、在当店员的、在当店长的卡
        ---1.先对所有的卡的数据进行排序, 可以当店员或者店长的排最后面

        ---2.当前编队心情值为0的可以替换
        local curTeamId = checkNumber(self.teams[self.selectIndex]) ---当前选中的编队id
        local allCards = t
        --for k, v in pairs(t) do
        --    ---@type MaidCoffeeCardInfoVo
        --    local vo = MaidCoffeeUtils.GetCardManagerInfoVo(v.cardId)
        --    if vo then
        --        if checkNumber(vo.job) == MaidCoffeeConstants.SelectType.Manager or checkNumber(vo.job) == MaidCoffeeConstants.SelectType.Clerk then
        --            table.insert(allCards, v)
        --        else
        --            table.insert(allCards, 1, v)
        --        end
        --    end
        --end
        for i, v in pairs(allCards) do
            local isHave = 0
            ----当前卡的状态
            local cafeStatus = checkNumber(v.cafeStatus)
            --if not limitStatus2Status[cafeStatus] then
            ---只选择在空闲中的卡牌
            if cafeStatus == MaidCoffeeConstants.CafeStatus.Non then
                --- 表示可以送外卖的卡牌
                for teamId, cards in pairs(allTeam) do
                    for i, playerCardId in pairs(cards) do
                        ---如果是当前选中的编队
                        if checkNumber(v.id) == checkNumber(playerCardId) then
                            isHave = 1
                        end
                    end
                end
                if isHave == 0 and checkNumber(v.cafeEnergy) > 0 then
                    ---外卖员
                    table.insert(showCard, v)
                end
            end
        end
        SortByMember(showCard, "cafeEnergy")
        local targetCards = {}
        for _, v in pairs(showCard) do
            ---@type MaidCoffeeCardInfoVo
            local vo = MaidCoffeeUtils.GetCardManagerInfoVo(v.cardId)
            if vo then
                if table.find(vo.job, function(v)
                    return checkNumber(v) == MaidCoffeeConstants.SelectType.DeliveryMan
                end) then
                    table.insert(targetCards, v)
                end
            end
        end
        showCard = targetCards
        if #showCard > 0 then
            ---当前已上阵的卡
            local inCards = maidCoffeePlayerComponent:GetCardsByTeamId(self.teams[self.selectIndex])
            local curTeamData = {}
            ---@type MaidCoffeeTakeOutOrderVo
            local takeOutOrderVo = MaidCoffeeUtils.GetMaidCoffeeTakeOutOrderVo(checkNumber(self.data.orderId))
            local moodNum = 0
            if takeOutOrderVo then
                moodNum = self:GetConsumeMood(takeOutOrderVo)
            end
            local num = 0
            for _, playerCardId in pairs(inCards) do
                local dojo = cardComponent:GetCardById(playerCardId)
                if checkNumber(dojo.cafeEnergy) > 0 then
                    table.insert(curTeamData, playerCardId)
                end
                num = num + checkNumber(dojo.cafeEnergy)
            end
            --整队心值不够时,第一优先级
            if num < moodNum and num > 0 then
                curTeamData = {} --整队替换的逻辑
                for _, playerCardId in pairs(inCards) do
                    local dojo = cardComponent:GetCardById(playerCardId)
                    if dojo then
                        dojo:UpdateCafeStatus(MaidCoffeeConstants.CafeStatus.Non)
                    end
                end
                SortByMember(showCard, "cafeEnergy", false)
            end
            local start = #curTeamData
            if start ~= PER_TEAM_CARDS then
                for i = start + 1, PER_TEAM_CARDS do
                    if showCard[i] then
                        ---存在时
                        table.insert(curTeamData, checkNumber(showCard[i].id))
                    end
                end
            end
            --local curTeamId = self.teams[self.selectIndex]
            maidCoffeePlayerComponent:UpdateRemoteTeamByTeamId(curTeamId, curTeamData, function()
                ---刷新外卖员加成信息
                self:FreshTeamUI()
            end)
        else
            GameUtils.Toast(localize("当前没有可以派送外卖的成员"))
        end
    end)
    SetButtonAction(self.FontStyleButton2, function()
        ---是否是领取等各状态
        local status = checkInt(self.data.status)
        if status == Status.IDLE then
            if self.canOrder == 1 then
                local curTeamId = self.teams[self.selectIndex]
                local teamStatus = maidCoffeePlayerComponent:GetTakeoutTeamStatus(curTeamId)
                if teamStatus == MaidCoffeeConstants.TakeOutStatus.PROGRESSING or teamStatus == MaidCoffeeConstants.TakeOutStatus.FINISHED then
                    GameUtils.Toast(localize('当前车队正在工作中'))
                    return
                end
                local cards = maidCoffeePlayerComponent:GetCardsByTeamId(curTeamId)
                if #cards > 0 then
                    ---@type MaidCoffeeTakeOutOrderVo
                    local takeOutOrderVo = MaidCoffeeUtils.GetMaidCoffeeTakeOutOrderVo(checkNumber(self.data.orderId))
                    if takeOutOrderVo then
                        ---@type CardComponent
                        local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
                        local mood = self:GetConsumeMood(takeOutOrderVo)
                        local total = 0
                        for i, playerCardId in pairs(cards) do
                            total = total + checkNumber(cardComponent:GetCardById(playerCardId).cafeEnergy)
                        end
                        if total >= mood then
                            local t = {}
                            local orderData = self.data
                            for _, v in pairs(orderData.cooks) do
                                local goodsId = checkNumber(v.cookId)
                                table.insert(t, { goodsId = goodsId, num = -checkNumber(v.num) * self.data.canOrderNum })
                            end
                            GameUtils.Request(Interfaces.MaidCoffeeTakeoutStart, {
                                orderId = self.data.id, teamId = curTeamId,num = self.data.canOrderNum
                            }, function(request, response)
                                if checkNumber(response.errCode) == 0 then
                                    ---成功了
                                    local data = checkTable(response.data)
                                    local order = checkTable(data.order)
                                    order.id = orderData.id
                                    GoodsUtils.DrawRewards(t)
                                    xTry(function()
                                        if data.cardsEnergy then
                                            for id, energy in pairs(data.cardsEnergy) do
                                                cardComponent:UpdateCardDojo(id, { cafeEnergy = checkNumber(energy), cafeStatus = MaidCoffeeConstants.CafeStatus.Non })
                                            end
                                        end
                                    end)
                                    Events.Broadcast(Constants.EventNames.EVENT_TAKEOUT_POPUP_FINISHED, { data = order , isNewOrder = 1})
                                    maidCoffeePlayerComponent:UpdateTakeOutAllTimes(data.allTakeoutTimes)
                                    if #data.rewards > 0 then
                                        GoodsUtils.DrawRewards(data.rewards)
                                        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = data.rewards,cb = function()
                                            UIModule.BackDialog()
                                        end } })
                                    else
                                        UIModule.BackDialog()
                                    end

                                end
                            end)
                        else
                            GameUtils.Toast(localize('请选择编队卡牌心情值不足不能配送'))
                        end
                    end
                else
                    GameUtils.Toast(localize('请选择编队'))
                end
            else
                ---跳转到料理制作
                local t = {}
                local data = self.data
                for _, v in pairs(data.cooks) do
                    local goodsId = checkNumber(v.cookId)
                    table.insert(t, { goodsId = goodsId, num = checkNumber(v.num) })
                end
                ---@type MaidCoffeeTakeOutOrderVo
                local takeOutOrderVo = MaidCoffeeUtils.GetMaidCoffeeTakeOutOrderVo(checkNumber(data.orderId))
                UIModule.OpenDialog(UIArgs(Constants.UITypeIds.UIMaidCoffeeCookingMainDialog, { type = MaidCoffeeConstants.CookingType.TakeOut,
                                                                                                data = t,
                                                                                                dojo = data,
                                                                                                vo = takeOutOrderVo,
                                                                                                cb = function()
                                                                                                    self:FreshUI()
                                                                                                end }))
            end
        elseif status == Status.FINISHED then
            ---领取的逻辑
            GameUtils.Request(Interfaces.MaidCoffeeTakeoutDraw, {
                type = 1, orderId = self.data.id
            }, function(request, response)
                if checkNumber(response.errCode) == 0 then
                    ---成功了
                    local data = checkTable(response.data)
                    local rewards = checkTable(data.rewards)
                    --GoodsUtils.DrawRewards(rewards)
                    ---@type CardComponent
                    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
                    local v = maidCoffeePlayerComponent:GetCardsByTeamId(self.data.teamId)
                    for _, id in pairs(v) do
                        cardComponent:UpdateCardDojo(id, { cafeStatus = MaidCoffeeConstants.CafeStatus.Non })
                    end
                    if #rewards > 0 then
                        GoodsUtils.DrawRewards(data.rewards)
                        Events.Broadcast(Constants.EventNames.EVENT_TAKEOUT_POPUP_FINISHED, { data = self.data, isNewOrder = 1 })
                        ---关闭当前的页面
                        kTool.SetActive(self.controller.gameObject, false)
                        UIModule.OpenDialog(
                                {
                                    id = Constants.UITypeIds.UICommonRewardPop,
                                    parameters = { rewards = data.rewards, cb = function()
                                        UIModule.BackDialog()
                                    end }
                                }
                        )
                    end
                end
            end)
        elseif status == Status.PROGRESSING then
            ---可快速完成的逻辑
            ---@type GoodsVo
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(Constants.Currency.CoffeeTakeoutTicket)
            local ticket = 1
            local remainTime = checkNumber(self.data.remainTime)
            local fixTime = 0
            if vo.effectType == Constants.GoodsEffectType.EffectShortTime then
                ---缩短时间
                if remainTime > 0 then
                    ticket = math.ceil(remainTime / checkNumber(vo.effectNum))
                end
                fixTime = checkNumber(vo.effectNum)
            end
            local havNo = GoodsUtils.GetThingNo(vo.id)
            local text = string.format_size_tag(string.format_color_tag(second_toHHMMSS(self.data.remainTime), '#d7184a'), 42)
            GameUtils.SecondConfirm(localize('是否使用_num_个_name_立即完成订单', { _num_ = ticket, _name_ = vo.name }), function()
                if havNo < ticket then
                    GameUtils.Toast(localize("_name_不足, 不能立即完成", { _name_ = vo.name }))
                    return
                end
                GameUtils.Request(Interfaces.MaidCoffeeTakeoutDraw, {
                    type = 2, orderId = self.data.id
                }, function(request, response)
                    if checkNumber(response.errCode) == 0 then
                        ---成功了
                        local data = checkTable(response.data)
                        local rewards = checkTable(data.rewards)
                        GoodsUtils.DrawRewards({ { goodsId = vo.id, num = -ticket } })
                        ---@type CardComponent
                        local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
                        local v = maidCoffeePlayerComponent:GetCardsByTeamId(self.data.teamId)
                        for _, id in pairs(v) do
                            cardComponent:UpdateCardDojo(id, { cafeStatus = MaidCoffeeConstants.CafeStatus.Non })
                        end

                        if #rewards > 0 then
                            GoodsUtils.DrawRewards(data.rewards)
                            Events.Broadcast(Constants.EventNames.EVENT_TAKEOUT_POPUP_FINISHED, { data = self.data, isNewOrder = 1 })
                            ---关闭当前的页面
                            kTool.SetActive(self.controller.gameObject, false)
                            UIModule.OpenDialog(
                                    {
                                        id = Constants.UITypeIds.UICommonRewardPop,
                                        parameters = { rewards = data.rewards, cb = function()
                                            UIModule.BackDialog()
                                        end }
                                    }
                            )
                        end
                    end
                end)

            end, function()

            end, text, 4, { { goodsId = Constants.Currency.CoffeeTakeoutTicket, num = ticket } }, false, localize('每张外卖券可缩短_time_', { _time_ = CS.Engine.Tools.TimeUtils.HumanizeTimeString(fixTime) }), nil, checkNumber(self.data.id), UIModule.RootCanvas.transform)
        end
    end)
    for i, v in pairs(self.data.cooks) do
        local goodsId = checkNumber(v.cookId)
        local haveNo = GoodsUtils.GetThingNo(goodsId)
        if checkNumber(v.num) > haveNo then
            ----如果存在不足时
            self.canOrder = 0
            break
        end
    end

    ---左右按钮的事件处理
    SetButtonAction(self.BtnArrowL, function(event)
        self.selectIndex = self.selectIndex - 1
        if self.selectIndex < 1 then
            self.selectIndex = 1
        end
        self:FreshTeamUI()
    end)
    SetButtonAction(self.BtnArrowR, function(event)
        self.selectIndex = self.selectIndex + 1
        if self.selectIndex > #self.teams then
            self.selectIndex = #self.teams
        end
        self:FreshTeamUI()
    end)

    self.EventEveryThingChangeEventName = Events.AddListener(Constants.EventNames.EveryThingChangeEventName, Bind(self, self.OnEveryThingChangeEventName))
end
function CoffeeTakeoutPopupDialog:RemoveListener()
    Events.RemoveListener(Constants.EventNames.EveryThingChangeEventName, self.EventEveryThingChangeEventName)
    self.EventEveryThingChangeEventName = nil
end

function CoffeeTakeoutPopupDialog:RefreshBtnAndNumShow(num,status)
    CfUtils.FillText(self.TextNumber,num)
    CfUtils.SetUISwitchText(self.TextNumber,status and 1 or 2)
    local style = status and "B25" or "B18"
    self.deliveryButtonEnv:ResetFontStyle(style, localize("开始配送"))
    kTool.SetActive(self.UIFX_RedGlow.gameObject,not status)
end
function CoffeeTakeoutPopupDialog:OnEveryThingChangeEventName(id)
    if not isNull(id) then
        return
    end
    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    ----更新下数据信息
    self.data = maidCoffeePlayerComponent:GetTakeoutOrdersById(self.data.id)
    self.canOrder = 1
    for i, v in pairs(self.data.cooks) do
        local goodsId = checkNumber(v.cookId)
        local haveNo = GoodsUtils.GetThingNo(goodsId)
        if checkNumber(v.num) > haveNo then
            ----如果存在不足时
            self.canOrder = 0
            break
        end
    end
    self:FreshUI()
end

---FreshTeamUI
---刷新编队ui
function CoffeeTakeoutPopupDialog:FreshTeamUI()
    if #self.teams == 1 then
        kTool.SetActive(self.BtnArrowL.gameObject, false)
        kTool.SetActive(self.BtnArrowR.gameObject, false)
    else
        if self.selectIndex <= 1 then
            kTool.SetActive(self.BtnArrowL.gameObject, false)
            kTool.SetActive(self.BtnArrowR.gameObject, true)
        elseif self.selectIndex >= #self.teams then
            kTool.SetActive(self.BtnArrowL.gameObject, true)
            kTool.SetActive(self.BtnArrowR.gameObject, false)
        else
            kTool.SetActive(self.BtnArrowL.gameObject, true)
            kTool.SetActive(self.BtnArrowR.gameObject, true)
        end
    end
    ---如果订单的状态是进行中的情况
    if checkNumber(self.data.status) == Status.PROGRESSING or checkNumber(self.data.status) == Status.FINISHED then
        kTool.SetActive(self.BtnArrowL.gameObject, false)
        kTool.SetActive(self.BtnArrowR.gameObject, false)
    end
    local textName = self.BtnArrowL.transform.parent.parent:Find("Name/TextName")
    local curTeamId = self.teams[self.selectIndex]
    if textName then
        local vo = MaidCoffeeUtils.GetMaidCoffeeClerkSettingVo(curTeamId)
        if vo then
            CfUtils.FillText(textName, vo.carName)
        end
    end
    ---获取配表列表
    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local status = maidCoffeePlayerComponent:GetTakeoutTeamStatus(curTeamId)
    if status == MaidCoffeeConstants.TakeOutStatus.PROGRESSING or status == MaidCoffeeConstants.TakeOutStatus.FINISHED then
        ---忙录中的队伍
        if checkNumber(self.data.status) == 0 then
            kTool.SetActive(self.UnderwayTips.gameObject, true)
            kTool.SetActive(self.FontStyleButton.gameObject, false)
            kTool.SetActive(self.FontStyleButton2.gameObject, true)
        else
            kTool.SetActive(self.UnderwayTips.gameObject, true)
            kTool.SetActive(self.FontStyleButton.gameObject, false)
            kTool.SetActive(self.FontStyleButton2.gameObject, true)
        end
    elseif status == MaidCoffeeConstants.TakeOutStatus.IDLE then
        ---空闲中
        kTool.SetActive(self.FontStyleButton.gameObject, true)
        kTool.SetActive(self.FontStyleButton2.gameObject, true)
        kTool.SetActive(self.UnderwayTips.gameObject, false)
    end
    ---获取当前编队的卡牌人数
    local cards = maidCoffeePlayerComponent:GetCardsByTeamId(curTeamId)
    ---@type CardComponent
    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)

    ---刷新卡牌
    for i = 1, PER_TEAM_CARDS do
        local goTrans = self.TeamMember:Find("BtnHead" .. tostring(i))
        if goTrans then
            ---@type TakeoutTeamHeadNode
            local env = CfUtils.GetLuaScr(goTrans.gameObject, HeadNodePath)
            if i <= #cards then
                ---@type CardDojo
                local dojo = cardComponent:GetCardById(cards[i])
                env:FreshUI(dojo)
            else
                env:FreshUI(nil)
            end
        end
    end
    ---刷新外卖员加成信息
    if #cards > 0 then
        --kTool.SetActive(self.ScrollView.transform.parent.gameObject, true)
        kTool.DestroyGameObjectChildren(self.Content.gameObject, false)
        local skills = {}
        local total = 0
        for i = 1, #cards do
            ---@type CardDojo
            local dojo = cardComponent:GetCardById(cards[i])
            if dojo then
                ---@type MaidCoffeeCardInfoVo
                local vo = MaidCoffeeUtils.GetCardManagerInfoVo(dojo.cardId)
                total = total + checkNumber(dojo.cafeEnergy)
                if vo then
                    ---存在经营技能
                    ---@type MaidCoffeeSkillVo
                    local skillVo = MaidCoffeeUtils.GetMaidCoffeeSkillInfoVo(vo.additionId)
                    if skillVo and skillVo.isTakeout == 1 then
                        if skills[tostring(vo.additionId)] then
                            table.insert(skills[tostring(vo.additionId)], { descr = skillVo.decr, additionNum = vo.additionNum })
                        else
                            skills[tostring(vo.additionId)] = { { descr = skillVo.decr, additionNum = vo.additionNum } }
                        end
                    end
                end
            end
        end
        local takeOutOrderVo = MaidCoffeeUtils.GetMaidCoffeeTakeOutOrderVo(checkNumber(self.data.orderId))
        local mood = self:GetConsumeMood(takeOutOrderVo)
        self:RefreshBtnAndNumShow(total,total >= mood)
        local keys = sortByKey(skills)
        for i, additionId in ipairs(keys) do
            local skillItem = skills[additionId]
            local skill = table.remove(skillItem, 1)
            local extra = nil
            if #skillItem > 0 then
                extra = skillItem
            end
            local go = kTool.Instantiate(self.Content.gameObject, self.Cell.gameObject, false)
            kTool.SetActive(go, true)
            if math.floor(i % 2) == 0 then
                CfUtils.SetUISwitchImage(go.transform:Find("ImgBg"), 2)
            else
                CfUtils.SetUISwitchImage(go.transform:Find("ImgBg"), 1)
            end
            ---根据规则优先处理_target_id_
            CfUtils.FillText(go.transform:Find("TextDesc"), MaidCoffeeUtils.FillCoffeeSkillDescription(skill.descr, skill.additionNum, extra,skill.percentage))
        end
        if table.count(skills) == 0 and self.Empty then
            kTool.SetActive(self.Empty.gameObject, true)
            kTool.SetActive(self.ScrollView.gameObject, false)
        else
            kTool.SetActive(self.Empty.gameObject, false)
            kTool.SetActive(self.ScrollView.gameObject, true)
        end
    else
        kTool.SetActive(self.ScrollView.transform.parent.gameObject, false)
    end
end

---OnTeamCardAction
---编辑队伍信息的回调
---@param position number
function CoffeeTakeoutPopupDialog:OnTeamCardAction(position)
    print('--->>', position)
    local status = checkInt(self.data.status)
    if status == Status.IDLE then
        ---只有空闲状态下才能点击
        ---获取配表列表
        ---@type MaidCoffeePlayerComponent
        local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
        local curTeamId = self.teams[self.selectIndex]
        if maidCoffeePlayerComponent:GetTakeoutTeamStatus(curTeamId) == MaidCoffeeConstants.TakeOutStatus.IDLE then
            ---当前编队没有在配送中的时候才能进行人物选择
            local cards = maidCoffeePlayerComponent:GetCardsByTeamId(curTeamId)
            local t = {}
            for i = 1, PER_TEAM_CARDS do
                if i <= #cards then
                    table.insert(t, { index = i, id = checkNumber(cards[i]) })
                else
                    table.insert(t, { index = i, id = 0 })
                end
            end

            local _ignoreData = maidCoffeePlayerComponent:GetTakeOutIgnoreTeamCardsData(curTeamId)
            local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
            component:SaveCacheData(t)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UIMaidCoffeePersonSelectDialog, parameters = {
                data = t,
                ignoreData = _ignoreData,
                index = self.teams[self.selectIndex], ---这里把TeamId传过去
                type = MaidCoffeeConstants.SelectType.DeliveryMan,
                cb = nil } })
        end
    end
end

function CoffeeTakeoutPopupDialog:SelectRoleCallback(type,data)
    self:FreshTeamUI()
end

---SetEditable
---设置面板是否可编辑状态
function CoffeeTakeoutPopupDialog:SetEditable()
    local status = checkInt(self.data.status)
    if status == Status.PROGRESSING then
        kTool.SetActive(self.TextTips.gameObject, false)
        kTool.SetActive(self.FontStyleButton.gameObject, false)
        self.deliveryButtonEnv:ResetFontStyle("B25", localize("快速完成"))
        kTool.SetActive(self.BtnArrowL.gameObject, false)
        kTool.SetActive(self.BtnArrowR.gameObject, false)
        --kTool.SetActive(self.UnderwayTips.gameObject, true)
    elseif status == Status.FINISHED then
        kTool.SetActive(self.TextTips.gameObject, false)
        kTool.SetActive(self.FontStyleButton.gameObject, false)
        --kTool.SetActive(self.FontStyleButton2.gameObject, true)
        self.deliveryButtonEnv:ResetFontStyle("B25", localize("领取奖励"))
        kTool.SetActive(self.BtnArrowL.gameObject, false)
        kTool.SetActive(self.BtnArrowR.gameObject, false)
        --kTool.SetActive(self.UnderwayTips.gameObject, true)
    else
        kTool.SetActive(self.TextTips.gameObject, true)
        ---@type MaidCoffeeTakeOutOrderVo
        local takeOutOrderVo = MaidCoffeeUtils.GetMaidCoffeeTakeOutOrderVo(checkNumber(self.data.orderId))
        if takeOutOrderVo then
            local displayMood = self:GetConsumeMood(takeOutOrderVo)
            self.TextTips.text = localize('车队总共需_num_点心情值才可开始配送', { _num_ = displayMood })
        end
        kTool.SetActive(self.FontStyleButton.gameObject, true)
        if self.canOrder == 1 then
            self.deliveryButtonEnv:ResetFontStyle("B25", localize("开始配送"))
        else
            self.deliveryButtonEnv:ResetFontStyle("B7", localize("料理制作"))
        end
    end
    self:FreshTeamUI()
end

---GetConsumeMood
---@param takeOutOrderVo MaidCoffeeTakeOutOrderVo
function CoffeeTakeoutPopupDialog:GetConsumeMood(takeOutOrderVo)
    --local delta = GameUtils.GetPrivilegeCardAddNumByRefId(1, "takeOutMoodOff")
    local baseNum = checkNumber(takeOutOrderVo.mood) * (self.data.canOrderNum or 1)
    local globalTalentMgr = GlobalTalentMgr:GetInstance()
    baseNum = globalTalentMgr:CalcNum(baseNum, Constants.GlobalTalentEffectId.Id_13, false, function(data)
        -- "参数1：系统功能ID（默认2001：包含装备 晶片 例子 经验 4个副本）
        -- 参数2：不同日常本（1装备本2食材本3Boss本4升阶材料本6经验本5粒子本)
        -- 参数3：若2是晶片本（4），则是不同颜色晶片本关卡ID；若2是装备本（1），则是区域ID；若2是经验本和粒子本，则空"
        ---@type HomelandTalentUpLvVo
        --local vo        = data.vo
        return true
    end)
    return baseNum
end

function CoffeeTakeoutPopupDialog:FreshUI()
    self:SetEditable()
    ---@type TakeoutOrderCellNode
    local env = CfUtils.GetLuaScr(self.OverseaManageTakeoutCardNode.gameObject, OrderCellNodePath)
    if env then
        env:FreshUI(self.data)
        env:SetCalculationCallBack(Bind(self,self.RefreshMoodShow))
    end
end

function CoffeeTakeoutPopupDialog:RefreshMoodShow()
    if self.canOrder == 1 then
        local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
        local curTeamId = self.teams[self.selectIndex]
        local cards = maidCoffeePlayerComponent:GetCardsByTeamId(curTeamId)
        if #cards > 0 then
            ---@type MaidCoffeeTakeOutOrderVo
            local takeOutOrderVo = MaidCoffeeUtils.GetMaidCoffeeTakeOutOrderVo(checkNumber(self.data.orderId))
            if takeOutOrderVo then
                ---@type CardComponent
                local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
                local mood = self:GetConsumeMood(takeOutOrderVo)
                local total = 0
                for i, playerCardId in pairs(cards) do
                    total = total + checkNumber(cardComponent:GetCardById(playerCardId).cafeEnergy)
                end
                self:RefreshBtnAndNumShow(total,total>=mood)
            end
        end
    end
    local takeOutOrderVo = MaidCoffeeUtils.GetMaidCoffeeTakeOutOrderVo(checkNumber(self.data.orderId))
    if takeOutOrderVo then
        local displayMood = self:GetConsumeMood(takeOutOrderVo)
        self.TextTips.text = localize('车队总共需_num_点心情值才可开始配送', { _num_ = displayMood })
    end
end

function CoffeeTakeoutPopupDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:FreshUI()
    end))
    return coWait
end

function CoffeeTakeoutPopupDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.timeTickEvent = Events.AddListener(Constants.EventNames.EVENT_CONFIRM_TIME_TICK, Bind(self, self.OnTimeTick))
    end))
    return coWait
end

function CoffeeTakeoutPopupDialog:OnTimeTick(orderId, text)
    --正在配送<size=50><color=#d7184a>2:20:00</color></size>
    if self.data and checkNumber(self.data.id) == checkNumber(orderId) then
        if text == 1 then
            ----已完成，可以变成已领取状态
            self.data.status = Status.FINISHED
            ---更新状态
            self:SetEditable()
        end
    end
end

function CoffeeTakeoutPopupDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:RemoveListener()
        Events.RemoveListener(Constants.EventNames.EVENT_CONFIRM_TIME_TICK, self.timeTickEvent)
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return CoffeeTakeoutPopupDialog